{
  "name": "System Roles Manager",
  "description": "Carries the system:roles permission; assigned to m2m applications (see '12') that need the Role Management API's own OU-scoped access tier, granted through an ordinary role assignment rather than declared unilaterally on the application.",
  "ouId": "{{defaultOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{systemResourceServerId}}",
      "permissions": [
        "system:roles"
      ]
    }
  ]
}

{
  "name": "System Roles Viewer",
  "description": "Carries the system:roles:view permission; assigned to m2m applications that need read-only access to the Role Management API.",
  "ouId": "{{defaultOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{systemResourceServerId}}",
      "permissions": [
        "system:roles:view"
      ]
    }
  ]
}

{
  "handle": "a",
  "name": "A",
  "description": "Owns the roles being shared in this demo.",
  "parent": null
}

{
  "handle": "b",
  "name": "B",
  "description": "Root organization the role is shared to. Also owns roles of its own.",
  "parent": null
}

{
  "handle": "b-sub1",
  "name": "B-sub1",
  "description": "Existing child of B, present before reshare. Also owns a role of its own.",
  "parent": "{{bOuId}}"
}

{
  "handle": "ex-a",
  "name": "Ex-A",
  "description": "A root with no sharing relationship to the role, used for negative tests.",
  "parent": null
}

{
  "name": "Booking System",
  "description": "Handles booking operations for the role sharing demo",
  "identifier": "https://api.example.com/booking",
  "ouId": "{{aOuId}}"
}

{
  "name": "A Admins",
  "description": "A's own group, assigned to the role at creation time.",
  "ouId": "{{aOuId}}"
}

{
  "name": "B-sub1 Staff",
  "description": "Group belonging to the pre-existing B-sub1 OU.",
  "ouId": "{{bSub1OuId}}"
}

{
  "name": "B-sub1 Extra Staff",
  "description": "Second group used to exercise grant-scoped editability without colliding with an existing assignment.",
  "ouId": "{{bSub1OuId}}"
}

{
  "name": "Ex-A Staff",
  "description": "Group belonging to Ex-A, used for negative tests.",
  "ouId": "{{exAOuId}}"
}

{
  "name": "regional-manager",
  "description": "Regional manager role, shareable across B2B organization units",
  "ouId": "{{aOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{resourceServerId}}",
      "permissions": [
        "{{permissionView}}",
        "{{permissionManage}}"
      ]
    }
  ],
  "assignments": [
    {
      "type": "group",
      "id": "{{aGroupId}}"
    }
  ]
}

{
  "name": "b-native-role",
  "description": "A role the B created and owns itself, independent of anything shared to it",
  "ouId": "{{bOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{resourceServerId}}",
      "permissions": [
        "{{permissionView}}"
      ]
    }
  ]
}

{
  "name": "b-sub1-native-role",
  "description": "A role B-sub1 created and owns itself",
  "ouId": "{{bSub1OuId}}",
  "permissions": [
    {
      "resourceServerId": "{{resourceServerId}}",
      "permissions": [
        "{{permissionManage}}"
      ]
    }
  ]
}

{
  "handle": "b-sub1b",
  "name": "B-sub1b",
  "description": "Created after the allChildren reshare, to prove dynamic propagation.",
  "parent": "{{bOuId}}"
}

{
  "name": "B-sub1b Staff",
  "description": "Used to prove the new child OU is already shared to.",
  "ouId": "{{bSub1bOuId}}"
}

{
  "name": "exclusion-demo-role",
  "description": "A second role used only to demonstrate share/reshare exclusion policies",
  "ouId": "{{aOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{resourceServerId}}",
      "permissions": [
        "{{permissionView}}"
      ]
    }
  ]
}

{
  "handle": "b-sub2",
  "name": "B-sub2",
  "description": "Grandchild of B (child of B-sub1), used to demonstrate grant-scoped, scope-down-only editability without disturbing the reshareGrantId chain other folders depend on.",
  "parent": "{{bSub1OuId}}"
}

{
  "name": "B-sub1 Booking Service",
  "description": "A client application belonging to B-sub1, to be assigned the shared role",
  "ouId": "{{bSub1OuId}}",
  "type": "m2m",
  "inboundAuthConfig": [
    {
      "type": "oauth2",
      "config": {
        "grantTypes": [
          "client_credentials"
        ],
        "tokenEndpointAuthMethod": "client_secret_basic",
        "scopes": [
          "{{permissionView}}",
          "{{permissionManage}}"
        ]
      }
    }
  ]
}

{
  "handle": "b-sub2b",
  "name": "B-sub2b",
  "description": "A child of B-sub1, two levels below B, used to prove delegation is one hop at a time.",
  "parent": "{{bSub1OuId}}"
}

{
  "name": "chain-demo-role",
  "description": "Throwaway role for the delegation and chain-integrity demo",
  "ouId": "{{aOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{resourceServerId}}",
      "permissions": [
        "{{permissionView}}"
      ]
    }
  ]
}

{
  "name": "scoped-admin-b",
  "description": "Scoped admin client for scoped-admin-b, used to mint system:roles-scoped tokens",
  "ouId": "{{bOuId}}",
  "type": "m2m",
  "inboundAuthConfig": [
    {
      "type": "oauth2",
      "config": {
        "grantTypes": [
          "client_credentials"
        ],
        "tokenEndpointAuthMethod": "client_secret_basic",
        "scopes": [
          "system:roles",
          "system:user"
        ],
        "token": {
          "accessToken": {
            "userConfig": {
              "validityPeriod": 3600
            },
            "clientConfig": {
              "attributes": [
                "sub_type",
                "ouId"
              ]
            }
          },
          "idToken": {
            "validityPeriod": 3600,
            "responseType": "JWT"
          },
          "refreshToken": {
            "validityPeriod": 86400
          }
        }
      }
    }
  ]
}

{
  "name": "scoped-admin-b-sub1",
  "description": "Scoped admin client for scoped-admin-b-sub1, used to mint system:roles-scoped tokens",
  "ouId": "{{bSub1OuId}}",
  "type": "m2m",
  "inboundAuthConfig": [
    {
      "type": "oauth2",
      "config": {
        "grantTypes": [
          "client_credentials"
        ],
        "tokenEndpointAuthMethod": "client_secret_basic",
        "scopes": [
          "system:roles"
        ],
        "token": {
          "accessToken": {
            "userConfig": {
              "validityPeriod": 3600
            },
            "clientConfig": {
              "attributes": [
                "sub_type",
                "ouId"
              ]
            }
          },
          "idToken": {
            "validityPeriod": 3600,
            "responseType": "JWT"
          },
          "refreshToken": {
            "validityPeriod": 86400
          }
        }
      }
    }
  ]
}

{
  "name": "scoped-admin-b-view",
  "description": "Scoped admin client for scoped-admin-b-view, used to mint system:roles:view-scoped tokens",
  "ouId": "{{bOuId}}",
  "type": "m2m",
  "inboundAuthConfig": [
    {
      "type": "oauth2",
      "config": {
        "grantTypes": [
          "client_credentials"
        ],
        "tokenEndpointAuthMethod": "client_secret_basic",
        "scopes": [
          "system:roles:view"
        ],
        "token": {
          "accessToken": {
            "userConfig": {
              "validityPeriod": 3600
            },
            "clientConfig": {
              "attributes": [
                "sub_type",
                "ouId"
              ]
            }
          },
          "idToken": {
            "validityPeriod": 3600,
            "responseType": "JWT"
          },
          "refreshToken": {
            "validityPeriod": 86400
          }
        }
      }
    }
  ]
}

{
  "name": "export-demo-role",
  "description": "Throwaway role demonstrating that export and import round-trip a role's grants and per-sharee-OU assignments, not just its core config",
  "ouId": "{{bOuId}}",
  "permissions": [
    {
      "resourceServerId": "{{resourceServerId}}",
      "permissions": [
        "{{permissionView}}"
      ]
    }
  ],
  "assignments": [
    {
      "type": "group",
      "id": "{{bGroupId}}"
    }
  ]
}
